declare @min int, @max int, @caixa varchar(8)
select @min = min(id), @max = max(id) from @tabcaixa

while @min <= @max
begin
	print @min
	select @caixa = caixa 
	from @tabcaixa
	where id = @min

	exec DBO.PRC_EXCLUI_CAIXA_AVULSA @caixa
	set @min = @min + 1
end

